import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"63、【既濟】 離下坎上","description":"周易尚氏學 - 63、【既濟】 離下坎上","frontmatter":{"title":"63、【既濟】 離下坎上","description":"周易尚氏學 - 63、【既濟】 離下坎上"},"headers":[],"relativePath":"classics/shangshi/068.md","filePath":"classics/shangshi/068.md"}'),s={name:"classics/shangshi/068.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_63、【既濟】-離下坎上" tabindex="-1">63、【既濟】 離下坎上 <a class="header-anchor" href="#_63、【既濟】-離下坎上" aria-label="Permalink to “63、【既濟】 離下坎上”">​</a></h1><p>爾雅釋天。濟謂之齊。疏霽止也。說文同。歸藏作岑昕（上雨）。昕（上雨）即霽字。上坎為雨。下離為日。雨過日出。故曰既濟。謙傳天道下濟。即下止也。詩庸（右邑）風。不能旋濟。傳濟止也。莊子齊物論。厲風濟則萬竅為虛。注濟止也。彖傳曰終止。雜卦曰既濟定。亦皆訓濟為止。既者盡也。左傳桓三年。日有食之既是也。既濟者言六爻盡當位而止其所也。止其所而不遷。則道窮。故彖辭不許其終吉。釋文釋濟為度。太玄釋為成。惟彖傳曰終止。即明釋既義。濟義。既者盡也。終也。終止即既濟。後儒紛紜不已者。以忽略終止。即說卦義也。六爻皆當位有應。故亨。小利貞小字。俞樾雲。衍文。卦辭只回亨利貞。故傳特以小者亨也釋之。如原有小字。則人人皆知。傳不如此釋矣。子夏傳虞翻皆以亨小斷句。似非。毛奇齡雲。宜以既濟亨句小利貞句。小利貞與小利有攸往同。按毛說於句讀適矣。然傳曰剛柔正。是兼大小言也。今專以屬之小。於六交當位之義不合。然則小字屬上下讀皆不安。徵之彖傳。其為衍文無疑。俞氏之說。似為可信。蓋易之為道。以陽為主。陰與陽絕不平等。故陰得陽應必吉。陽得陰應則不必吉。且有以為兇者。如大過四爻。中孚初爻皆是。既濟二四承乘皆陽。又三陰皆有陽應。故小者亨、彖傳專以亨屬小。亦謂大者不然。大何以不然。凡陽遇重陰必吉。一陰則否。既濟三五皆陷陰中。雖三陽皆得位有應。然所應者陰。固與柔爻異也。此傳之所以專以亨屬之小也。既濟者終止。其在既濟之初。上下得所。民物咸宜。故初吉。然易之道以變通為貴。無或休息。止而終於是。則易道窮矣。故終亂。</p><p>彖曰。既濟亨。小者亨也。利貞。剛柔正而位當也初吉。柔得中也。終止則亂。其道窮也。</p><p>卦三陰三陽。二為陰始得中。放曰初吉。上六則陰之終。故日終止。則亂。坤為亂也。五剛亦得中。不許其吉者。以陷於陰中。與柔得中異也。</p><p>象曰。水在火上。既濟。君子以思患而預防之。</p><p>治亂相循環。當治不可忘亂。坎為患為心。故曰思患。</p><p>初九。曳其輪。濡其尾。無咎。</p><p>初應在四。四坎為曳。為輪。為儒。四居坎下。故曰曳。曰尾。所有象皆在應爻。舊解苦於本爻求。胡能合乎。曳儒當有咎。得正故無咎。</p><h3 id="象曰。曳其輪。義無咎也。" tabindex="-1">象曰。曳其輪。義無咎也。 <a class="header-anchor" href="#象曰。曳其輪。義無咎也。" aria-label="Permalink to “象曰。曳其輪。義無咎也。”">​</a></h3><p>得正有應。當然無咎。</p><p>六二。婦喪其茀。匆逐。七日得。</p><p>左傳昭五年。火水妃也。故離為坎婦。茀車蔽也。詩碩人曰。翟茀以朝。疏婦人乘車不露兒。車之前後。障以翟羽。以自隱蔽。謂之茀。按周禮有巾車職。巾所以為蔽。即茀也。坎為隱伏為茀。乃坎在外。故喪其茀。蓋離為光明。二承乘皆陽。無所隱蔽。如婦人之喪其茀也。廬兆鱉雲。初曳輪。二喪弗。義實相因。其改字作紱作髟（下也）者。皆非也。震為逐。半震故勿逐。七日得者。震為復。數七。言至七日。自然來複。與震二同義也。</p><h3 id="象曰。七日得。以中道也" tabindex="-1">象曰。七日得。以中道也 <a class="header-anchor" href="#象曰。七日得。以中道也" aria-label="Permalink to “象曰。七日得。以中道也”">​</a></h3><p>二得中故得。</p><p>九三。高宗伐鬼方。三年克之。小人勿用。</p><p>易林於既未濟。偶用半象。本之易也。三四形震。震為帝為主。故曰高宗。曰伐。坎為三年。為鬼方。高宗殷王武丁。鬼方西美國名。範書西羌傳雲。殷室中衰。諸侯叛。至高宗伐西戎鬼方。三年乃克。又曰周季歷伐西落鬼戎是也。坎為艱為勞。故三年乃克。小人謂上六。覆上六雲。反君道。比上六雲。無首兇。師上六雲。小人勿用。是上六反君道。無道。為小人之尤。茲於三交發之者。以三應在上六。故預戒也。</p><h3 id="象曰。三年克之。憊也。" tabindex="-1">象曰。三年克之。憊也。 <a class="header-anchor" href="#象曰。三年克之。憊也。" aria-label="Permalink to “象曰。三年克之。憊也。”">​</a></h3><p>坎為勞。故曰憊。憊疲極也。</p><p>六四。襦有衣袖 終日戒。</p><p>此與解三用象同。襦說文繒采色。按繒說文帛也。三四震象。震為衣。襦有。言有帛衣也。四五巽象。巽為帛。亦為枷。如（左衣）敗絮也。襦有衣如（左衣）者。言雖有帛衣。衣敗絮以自晦。終日戒備也。離為日。坎為憂。故曰終日戒。蓋四居兩坎之間。坎為盜。俱有所侵犯。故惡衣以自晦。如（左衣）說文引作奴（下系）。釋文雲子夏作茹。茹柳奴（下系）音同故通用。又云京作絮。按絮即奴（下系）之形訛字。太玄迎道雲。裳有衣襦。裳者禮服。襦者短衣。乃有裳不用而衣襦。釋此句至為明晰。又釋文儒子夏作襦。薛虞雲。古文作襦。按襦儒古通。周禮羅氏注。鄭司農雲。襦為儒有衣絮之襦。弓人注。鄭司農雲。如（下巾）讀為襦有衣奴（下系）之奴（下系）。是襦儒枷古通用。故各家讀不同。</p><h3 id="象曰。終日戒。有所疑也。" tabindex="-1">象曰。終日戒。有所疑也。 <a class="header-anchor" href="#象曰。終日戒。有所疑也。" aria-label="Permalink to “象曰。終日戒。有所疑也。”">​</a></h3><p>坎為疑。</p><p>九五。東鄰殺牛。不如西鄰之論祭。實受其福。</p><p>離位東。故曰東鄰。坎位西。故曰西鄰。離為牛。兌為毀折為斧。故曰東鄰之殺牛。坎為飲食。故為祭。侖（左示）薄祭也。坎為薄。故曰西鄰之掄祭。乾為福。殺牛而祭。當受福矣。然不如掄祭受福者。以坎當五。得中正之時也。此離東坎西之確證。鄭氏謂離日出東。故曰東鄰。坎月生西。故曰西鄰。而不知離即在東。坎即在西。則卦象失傳之故也。又漢人往往以紂與文王之事說此爻。非。</p><h3 id="象曰。東鄰殺牛。不如西鄰之時也。實受其福。吉大來也。" tabindex="-1">象曰。東鄰殺牛。不如西鄰之時也。實受其福。吉大來也。 <a class="header-anchor" href="#象曰。東鄰殺牛。不如西鄰之時也。實受其福。吉大來也。" aria-label="Permalink to “象曰。東鄰殺牛。不如西鄰之時也。實受其福。吉大來也。”">​</a></h3><p>受福故吉。</p><p>上六。濡其首。厲。</p><p>坎為首。陰乘陽故襦其首。與比上六之無首義同。彖所謂終亂者此交。</p><h3 id="象曰。濡其首厲。何可久也。" tabindex="-1">象曰。濡其首厲。何可久也。 <a class="header-anchor" href="#象曰。濡其首厲。何可久也。" aria-label="Permalink to “象曰。濡其首厲。何可久也。”">​</a></h3><p>荀爽曰。居上襦五。處高居盛。必當復危。故何可久。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
